package com.pousadamarealta;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.junit.jupiter.api.*;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;

import static org.junit.jupiter.api.Assertions.*;

@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class ReservationSystemIT {
    private static final String BASE_URL = "http://localhost:7070";
    private static final HttpClient httpClient = HttpClient.newHttpClient();
    private static final ObjectMapper objectMapper = new ObjectMapper()
        .registerModule(new JavaTimeModule());

    private static Process serverProcess;

    @BeforeAll
    static void setup() throws IOException, InterruptedException, SQLException {
        setupTestDatabase();

        ProcessBuilder pb = new ProcessBuilder("java", "-jar", "target/reservas-1.0.0.jar");
        pb.environment().put("DB_URL", "jdbc:postgresql://localhost:5432/pousada_test");
        pb.environment().put("DB_USER", "postgres");
        pb.environment().put("DB_PASSWORD", "postgres");
        pb.environment().put("PORT", "7070");
        serverProcess = pb.start();

        Thread.sleep(3000);
    }

    @AfterAll
    static void teardown() {
        if (serverProcess != null) {
            serverProcess.destroy();
        }
    }

    private static void setupTestDatabase() throws SQLException {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/postgres", "postgres", "postgres");
             Statement stmt = conn.createStatement()) {

            stmt.execute("DROP DATABASE IF EXISTS pousada_test");
            stmt.execute("CREATE DATABASE pousada_test");
        }
    }

    @Test
    @Order(1)
    void testGetRooms() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/rooms"))
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());

        JsonNode rooms = objectMapper.readTree(response.body());
        assertEquals(5, rooms.size());
        assertEquals("101", rooms.get(0).get("number").asText());
        assertEquals("STANDARD", rooms.get(0).get("type").asText());
        assertEquals(2, rooms.get(0).get("capacity").asInt());
    }

    @Test
    @Order(2)
    void testCreateReservationWithCpf() throws IOException, InterruptedException {
        ObjectNode reservation = objectMapper.createObjectNode();
        reservation.put("roomNumber", "101");
        reservation.put("guestName", "João Silva");
        reservation.put("guestEmail", "joao@example.com");
        reservation.put("guestCpf", "111.222.333-44");
        reservation.put("checkIn", "2027-07-10");
        reservation.put("checkOut", "2027-07-12");
        reservation.put("guests", 2);
        reservation.put("ratePlan", "STANDARD");

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(reservation.toString()))
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());

        JsonNode created = objectMapper.readTree(response.body());
        assertEquals(1, created.get("id").asLong());
        assertEquals("PENDING", created.get("status").asText());
        assertEquals(2, created.get("nights").asInt());
        assertEquals(599.76, created.get("subtotal").asDouble(), 0.01);
        assertEquals(0, created.get("discount").asDouble(), 0.01);
        assertEquals(599.76, created.get("total").asDouble(), 0.01);
    }

    @Test
    @Order(3)
    void testCreateReservationWithCnpj() throws IOException, InterruptedException {
        ObjectNode reservation = objectMapper.createObjectNode();
        reservation.put("roomNumber", "201");
        reservation.put("guestName", "Ana Souza");
        reservation.put("guestEmail", "ana@example.com");
        reservation.put("companyCnpj", "12.345.678/0001-90");
        reservation.put("companyName", "Tecnosul Ltda");
        reservation.put("checkIn", "2027-03-10");
        reservation.put("checkOut", "2027-03-12");
        reservation.put("guests", 2);
        reservation.put("ratePlan", "NON_REFUNDABLE");

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(reservation.toString()))
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());

        JsonNode created = objectMapper.readTree(response.body());
        assertEquals(2, created.get("id").asLong());
        assertEquals("Tecnosul Ltda", created.get("companyName").asText());
        assertEquals(779.80, created.get("subtotal").asDouble(), 0.01);
        assertEquals(116.97, created.get("discount").asDouble(), 0.01);
        assertEquals(662.83, created.get("total").asDouble(), 0.01);
    }

    @Test
    @Order(4)
    void testCreateReservationWithPassport() throws IOException, InterruptedException {
        ObjectNode reservation = objectMapper.createObjectNode();
        reservation.put("roomNumber", "301");
        reservation.put("guestName", "John Smith");
        reservation.put("guestEmail", "john@example.com");
        reservation.put("guestPassport", "X1234567");
        reservation.put("guestCountry", "United Kingdom");
        reservation.put("checkIn", "2027-03-10");
        reservation.put("checkOut", "2027-03-12");
        reservation.put("guests", 4);
        reservation.put("ratePlan", "STANDARD");

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(reservation.toString()))
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(201, response.statusCode());

        JsonNode created = objectMapper.readTree(response.body());
        assertEquals("X1234567", created.get("guestPassport").asText());
        assertEquals("United Kingdom", created.get("guestCountry").asText());
    }

    @Test
    @Order(5)
    void testConfirmReservation() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations/1/confirmation"))
            .POST(HttpRequest.BodyPublishers.noBody())
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());

        JsonNode confirmed = objectMapper.readTree(response.body());
        assertEquals("CONFIRMED", confirmed.get("status").asText());
        assertEquals(599.76, confirmed.get("amountPaid").asDouble(), 0.01);
    }

    @Test
    @Order(6)
    void testGetMessages() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/messages"))
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());

        JsonNode messages = objectMapper.readTree(response.body());
        assertTrue(messages.size() > 0);
        assertEquals("EMAIL", messages.get(0).get("channel").asText());
        assertEquals("joao@example.com", messages.get(0).get("to").asText());
        assertEquals("Reserva confirmada - Pousada Maré Alta", messages.get(0).get("subject").asText());
        assertTrue(messages.get(0).get("body").asText().contains("Comprovante de reserva nº 1"));
    }

    @Test
    @Order(7)
    void testCheckIn() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations/1/check-in"))
            .POST(HttpRequest.BodyPublishers.noBody())
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());

        JsonNode checkedIn = objectMapper.readTree(response.body());
        assertEquals("CHECKED_IN", checkedIn.get("status").asText());
    }

    @Test
    @Order(8)
    void testCheckOut() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations/1/check-out"))
            .POST(HttpRequest.BodyPublishers.noBody())
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());

        JsonNode document = objectMapper.readTree(response.body());
        assertEquals("Comprovante de reserva", document.get("title").asText());
        assertEquals(1, document.get("reservationId").asLong());
        assertTrue(document.get("text").asText().contains("CPF 111.222.333-44"));
    }

    @Test
    @Order(9)
    void testGetDocument() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations/1/document"))
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());

        JsonNode document = objectMapper.readTree(response.body());
        assertEquals("Comprovante de reserva", document.get("title").asText());
    }

    @Test
    @Order(10)
    void testRoomUnavailable() throws IOException, InterruptedException {
        ObjectNode reservation = objectMapper.createObjectNode();
        reservation.put("roomNumber", "101");
        reservation.put("guestName", "Maria Santos");
        reservation.put("guestEmail", "maria@example.com");
        reservation.put("guestCpf", "555.666.777-88");
        reservation.put("checkIn", "2027-07-10");
        reservation.put("checkOut", "2027-07-12");
        reservation.put("guests", 2);
        reservation.put("ratePlan", "STANDARD");

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(reservation.toString()))
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(409, response.statusCode());

        JsonNode error = objectMapper.readTree(response.body());
        assertEquals("ROOM_UNAVAILABLE", error.get("error").asText());
    }

    @Test
    @Order(11)
    void testCapacityExceeded() throws IOException, InterruptedException {
        ObjectNode reservation = objectMapper.createObjectNode();
        reservation.put("roomNumber", "101");
        reservation.put("guestName", "Pedro Lima");
        reservation.put("guestEmail", "pedro@example.com");
        reservation.put("guestCpf", "999.888.777-66");
        reservation.put("checkIn", "2027-08-10");
        reservation.put("checkOut", "2027-08-12");
        reservation.put("guests", 5);
        reservation.put("ratePlan", "STANDARD");

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(reservation.toString()))
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(422, response.statusCode());

        JsonNode error = objectMapper.readTree(response.body());
        assertEquals("CAPACITY_EXCEEDED", error.get("error").asText());
    }

    @Test
    @Order(12)
    void testOccupancyReport() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reports/occupancy?date=2027-07-10"))
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        assertTrue(response.headers().firstValue("Content-Type").get().contains("text/csv"));

        String csv = response.body();
        assertTrue(csv.contains("room,type,reservation,check_in,check_out"));
        assertTrue(csv.contains("101,STANDARD,1,2027-07-10,2027-07-12"));
        assertTrue(csv.contains("total,1/5"));
    }

    @Test
    @Order(13)
    void testRevenueReport() throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reports/revenue?month=2027-07"))
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        assertEquals(200, response.statusCode());
        assertTrue(response.headers().firstValue("Content-Type").get().contains("text/csv"));

        String csv = response.body();
        assertTrue(csv.contains("reservation,room,check_in,check_out,status,amount"));
        assertTrue(csv.contains("1,101,2027-07-10,2027-07-12,CHECKED_OUT,599.76"));
        assertTrue(csv.contains("total,599.76"));
    }
}

